const body = $json.body || $json;
const outlet = (body.outlet || '').trim();
const recipient = (body.recipient_email || '').trim();
const force_refresh = body.force_refresh || false;

if (!outlet) {
  throw new Error('outlet is required. Send: {"outlet": "Reuters", "recipient_email": "you@email.com"}');
}

return [{
  outlet,
  recipient_email: recipient,
  force_refresh,
  outlet_slug: outlet.toLowerCase().replace(/ /g, '_')
}];

const results = $json.results || [];
const outlet = $('Parse Input').first().json.outlet;
const force_refresh = $('Parse Input').first().json.force_refresh;

if (results.length === 0 || force_refresh) {
  return [{ has_recent: false, outlet, source: 'fresh', notion_url: '', overall_score: 0, competitors: '', top_dimension: '' }];
}

const page = results[0];
const props = page.properties || {};
const generated = props.Generated?.date?.start || '';
const notion_url = page.url || '';
const overall_score = props['Overall Score']?.number || 0;
const competitors = props.Competitors?.rich_text?.[0]?.text?.content || '';
const top_dim = props['Top Dimension']?.rich_text?.[0]?.text?.content || '';

const generatedDate = new Date(generated);
const daysDiff = (Date.now() - generatedDate.getTime()) / (1000 * 60 * 60 * 24);
const is_recent = daysDiff <= 7;

return [{
  has_recent: is_recent,
  outlet,
  source: is_recent ? 'cache' : 'fresh',
  notion_url,
  overall_score,
  competitors,
  top_dimension: top_dim,
  generated,
  days_old: Math.round(daysDiff)
}];

// Store job_id for polling
const job_id = $json.job_id;
if (!job_id) throw new Error('No job_id returned from pipeline');
return [{ job_id, outlet: $('Parse Input').first().json.outlet }];

// Extract data from completed job or cache
const fromCache = $('Check Cache').first().json.has_recent;

let outlet, report, notion_url, overall_score, competitors, source;

if (fromCache) {
  const cache = $('Check Cache').first().json;
  outlet = cache.outlet;
  notion_url = cache.notion_url;
  overall_score = cache.overall_score;
  competitors = cache.competitors;
  source = 'cache';
  report = '';
} else {
  const job = $('Poll Job Status').first().json;
  outlet = job.outlet || $('Parse Input').first().json.outlet;
  report = job.report || '';
  notion_url = job.notion_url || '';
  overall_score = job.overall_score || 0;
  competitors = job.competitors || '';
  source = 'fresh';
}

// Extract executive summary from report
let summary = '';
if (report) {
  const lines = report.split('\n');
  let inExec = false;
  for (const line of lines) {
    if (line.includes('## Executive Summary')) { inExec = true; continue; }
    if (inExec && line.startsWith('## ')) break;
    if (inExec && line.trim()) summary += line.trim() + ' ';
    if (summary.length > 500) break;
  }
}

return [{ outlet, summary: summary.trim(), notion_url, overall_score, competitors, source, report }];

const outlet = $json.outlet;
const summary = $json.summary || 'See full report in Notion.';
const notion_url = $json.notion_url;
const score = $json.overall_score;
const competitors = $json.competitors;
const source = $json.source;
const date = new Date().toLocaleDateString('en-GB', {day:'numeric',month:'long',year:'numeric'});
const sourceLabel = source === 'cache' ? 'Retrieved from Notion library' : 'Freshly generated';

const html = `<!DOCTYPE html><html><head><meta charset="UTF-8"><style>
body{font-family:-apple-system,BlinkMacSystemFont,'Inter',sans-serif;background:#F8F5EF;margin:0;padding:0;}
.wrap{max-width:620px;margin:0 auto;background:#fff;}
.hdr{background:#0D1B2A;padding:32px 40px;border-bottom:3px solid #C0392B;}
.logo{font-family:Georgia,serif;font-size:22px;color:#fff;font-weight:700;margin-bottom:4px;}
.tag{font-size:10px;color:#8B92A5;letter-spacing:1.5px;text-transform:uppercase;}
.body{padding:36px 40px;}
.ey{font-size:10px;color:#C0392B;letter-spacing:2px;text-transform:uppercase;font-weight:700;margin-bottom:10px;}
.ot{font-family:Georgia,serif;font-size:32px;color:#0D1B2A;font-weight:700;margin-bottom:6px;}
.mt{font-size:13px;color:#8B92A5;margin-bottom:28px;}
.st{font-size:11px;font-weight:700;color:#8B92A5;letter-spacing:1.5px;text-transform:uppercase;margin:28px 0 12px;}
.sum{font-size:15px;line-height:1.75;color:#2D3748;background:#F8F5EF;padding:20px 24px;border-radius:8px;border-left:4px solid #C0392B;}
.sc{display:flex;align-items:center;justify-content:space-between;padding:12px 0;border-bottom:1px solid #E2DDD5;}
.sl{font-size:14px;color:#4A5568;}.sv{font-size:18px;font-weight:700;color:#0D1B2A;}
.btn{display:inline-block;background:#C0392B;color:#fff!important;padding:14px 28px;border-radius:8px;text-decoration:none;font-size:14px;font-weight:700;margin-top:8px;}
.bdg{display:inline-block;background:rgba(26,122,74,.1);color:#1A7A4A;padding:4px 12px;border-radius:12px;font-size:11px;font-weight:700;margin-bottom:20px;}
.ft{background:#F8F5EF;padding:24px 40px;border-top:1px solid #E2DDD5;font-size:12px;color:#8B92A5;text-align:center;line-height:1.6;}
</style></head><body>
<div class="wrap">
  <div class="hdr"><div class="logo">Media Intelligence Agent</div><div class="tag">Autonomous Competitive Benchmarking</div></div>
  <div class="body">
    <div class="ey">Intelligence Brief · ${sourceLabel}</div>
    <div class="ot">${outlet}</div>
    <div class="mt">${date}</div>
    ${competitors ? `<div class="bdg">vs ${competitors}</div>` : ''}
    <div class="st">Executive Summary</div>
    <div class="sum">${summary}</div>
    ${score ? `<div class="st">Overall Score</div><div class="sc"><div class="sl">Competitive Score</div><div class="sv">${Number(score).toFixed(2)}/5</div></div>` : ''}
    <div class="st">Full Report</div>
    ${notion_url ? `<a class="btn" href="${notion_url}">Open in Notion →</a>` : '<p style="color:#8B92A5;font-size:14px">Report saved to your reports library.</p>'}
  </div>
  <div class="ft">Generated by Media Intelligence Agent · Ironhack AI Engineering Module 3<br>Produced autonomously using 7 data sources and 54 LLM evaluations.</div>
</div></body></html>`;

return [{
  subject: `Media Intelligence Brief: ${outlet}`,
  html_body: html,
  recipient: $('Parse Input').first().json.recipient_email,
  outlet,
  notion_url
}];

